css:
.loader { position: relative; overflow: hidden; width: var(--loader-size); height: calc(var(--loader-size) * .28); border-radius: 9999px; border: calc(var(--loader-size) * .025) solid var(--loader-color); box-sizing: border-box; }
.loader .fill { position: absolute; top: 0; bottom: 0; left: 0; right: 0; border-radius: 9999px; background: var(--loader-color); animation: twGrow calc(var(--loader-speed) * 1.8) cubic-bezier(.4, 0, .2, 1) infinite; }
@keyframes twGrow { 0% { transform: scaleX(0); transform-origin: left center; } 45% { transform: scaleX(1); transform-origin: left center; } 55% { transform: scaleX(1); transform-origin: right center; } 100% { transform: scaleX(0); transform-origin: right center; } }
